sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {

          // Add your code here
	var report_sys_id = current.parent.sys_id;
	var subject_person = current.parent.subject_person; //Main inspector

	var gr = new GlideRecord('x_hccc_hoc_ohs_other_inspectors');
	var firstInspector=true;
	var inspectors_list = "";

	gr.query('parent_case',report_sys_id);
	while (gr.next()){
		if (gr.inspector.sys_id == subject_person){
			continue; 
		}
		if (firstInspector == true){
			inspectors_list+="" + gr.inspector.getDisplayValue();  
			firstInspector=false;
		}
		else
		{
			inspectors_list+=", " + gr.inspector.getDisplayValue();
		}
	}

	template.print(inspectors_list);

})(current, template, email, email_action, event);
